{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the fermentation liquid look like at the intended measurement point?"
    },
    {
      "question_id": "q2",
      "question": "Is there a known fluorescent compound, marker or reference relationship linked to either glucose concentration or viable biomass?"
    },
    {
      "question_id": "q3",
      "question": "Do you have reference methods that provide comparison values for glucose concentration and viable biomass?"
    },
    {
      "question_id": "q4",
      "question": "Have you already defined numerical acceptance criteria, such as accuracy or detection limits, for glucose concentration and viable biomass?"
    },
    {
      "question_id": "q5",
      "question": "Over what ranges must glucose concentration and viable biomass be followed?"
    },
    {
      "question_id": "q6",
      "question": "How quickly must glucose concentration and viable-biomass results be available?"
    }
  ],
  "plan": {
    "objective": "Assess whether the proposed measurements can meet client-agreed requirements for glucose concentration and viable biomass.",
    "samples_and_states": [
      {
        "text": "Collect representative fermentation samples spanning the agreed target ranges and relevant process states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Pair spectra with time-matched, independent reference measurements for glucose concentration and viable biomass.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Acquire matched spectra using the specified probe configurations at the measurement point agreed with the client.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare each candidate’s reference-calibrated estimates with the reference results separately for each target.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate each model on independent fermentation material excluded from calibration.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Proceed only for target–method pairs that meet acceptance criteria agreed with the client before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Do not accept a cell-density correlation alone as demonstration of viable-biomass measurement.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify appearance, fluorescence justification, references, ranges, acceptance criteria and timing.",
      "Collect samples spanning agreed target ranges and relevant fermentation states.",
      "Obtain time-matched glucose and viable-biomass reference measurements.",
      "Set up candidate probes, calibrate and compare with references.",
      "Validate on independent fermentation material excluded from calibration.",
      "Decide go or no-go against pre-agreed criteria for each target."
    ]
  },
  "decision_basis": [
    {
      "text": "Decide feasibility for each target by comparing estimates against reference measurements on independent material, using criteria agreed with the client before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
